WITH filtered AS (SELECT id, account_id, txn_type, amount, merchant, is_flagged, CASE WHEN amount >= 3100 THEN 'High' WHEN amount >= 1200 THEN 'Medium' ELSE 'Low' END AS amount_level, DATE_TRUNC('YEAR', txn_time) AS txn_time_period, COALESCE(merchant, 'N/A') AS resolved_merchant FROM transactions WHERE txn_time >= TIMESTAMP '2024-03-15 03:00:00') SELECT * FROM (SELECT account_id, merchant, amount FROM filtered) src PIVOT (MAX(amount) AS total, COUNT(1) AS n FOR merchant IN ('Grab' AS grab, 'Lazada' AS lazada));
